{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is enterprise fiber optic cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It is the fiber an organization runs in its own buildings and campus: plenum and riser rated cable for the in-building backbone, trunks and patch cords in the server room, and outdoor cable between buildings. Vocom supplies all three, built to order in 6 to 8 weeks."
      }
    },
    {
      "@type": "Question",
      "name": "Plenum or riser cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "OFNP is plenum rated for air handling spaces. OFNR is riser rated for vertical runs between floors. Plenum is the stricter rating, and the inspecting authority decides which one applies to your pathway."
      }
    },
    {
      "@type": "Question",
      "name": "Single-mode or multimode for an office or campus?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "OS2 single-mode for distance, such as building to building or long risers. OM3 and OM4 multimode for short reach inside a server room or a row. The deciding factor is the link budget on the longest run."
      }
    },
    {
      "@type": "Question",
      "name": "Can you supply cable between buildings?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Outdoor loose tube cable (GCYFTY and GYFS) for outdoor duct routes, and armored direct burial cable where it goes straight into the ground. See loose tube fiber optic cable ."
      }
    },
    {
      "@type": "Question",
      "name": "Do you supply patch cords and connectors?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. LC, SC, FC, ST and MTRJ patch cords, MTP and MPO assemblies, adapters and armored patch cords, built to your connector, polish, jacket and length. See patch cords, connectors and hardware ."
      }
    },
    {
      "@type": "Question",
      "name": "Do you install the cable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Vocom supplies the cable and assemblies, and your installer or contractor fits them. Contractors who carry material in their scope can order directly."
      }
    },
    {
      "@type": "Question",
      "name": "What is the lead time?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "6 to 8 weeks from PO, 2 to 3 weeks expedited by air, and up to 10 weeks for custom builds. Larger orders can be split across ship dates."
      }
    },
    {
      "@type": "Question",
      "name": "What should I send for a quote?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fiber count, fiber type, construction, rating (OFNP, OFNR or LSZH), footage per run, connectors if the cable is terminated, and the needed-by date."
      }
    }
  ]
